-- CSCI 41: Venue Management Database
-- SELECT statements used by the system (generated by: python manage.py export_queries)
-- Values are samples. In the app they come from the URL or the logged-in user.

-- 1. Venue list filter: building dropdown options
-- Used by: GET /venues/
SELECT "BUILDING"."Building_ID", "BUILDING"."Building_Name", "BUILDING"."Street", "BUILDING"."District", "BUILDING"."City", "BUILDING"."Acquisition_Date" FROM "BUILDING" ORDER BY "BUILDING"."Building_Name" ASC;

-- 2. Venue list filter: venue type dropdown options
-- Used by: GET /venues/
SELECT DISTINCT "VENUE"."Venue_Type" AS "venue_type" FROM "VENUE" ORDER BY 1 ASC;

-- 3. Venue list filter: amenity dropdown options
-- Used by: GET /venues/
SELECT "AMENITY_TYPE"."Amenity_ID", "AMENITY_TYPE"."Amenity_Name" FROM "AMENITY_TYPE" ORDER BY "AMENITY_TYPE"."Amenity_Name" ASC;

-- 4. Venue search by building, type, capacity and amenity
-- Used by: GET /venues/?building=BLDG1001&type=Gym&min_capacity=100&amenities=AMTY1001
SELECT DISTINCT "VENUE"."Venue_ID", "VENUE"."Venue_Name", "VENUE"."Venue_Type", "VENUE"."Floor", "VENUE"."Floor_Area_Sqm", "VENUE"."Capacity", "VENUE"."Building_ID", "BUILDING"."Building_ID", "BUILDING"."Building_Name", "BUILDING"."Street", "BUILDING"."District", "BUILDING"."City", "BUILDING"."Acquisition_Date" FROM "VENUE" INNER JOIN "BUILDING" ON ("VENUE"."Building_ID" = "BUILDING"."Building_ID") INNER JOIN "VENUE_AMENITY" ON ("VENUE"."Venue_ID" = "VENUE_AMENITY"."Venue_ID") WHERE ("VENUE"."Building_ID" = 'BLDG1001' AND "VENUE"."Venue_Type" = 'Gym' AND "VENUE"."Capacity" >= 100 AND "VENUE_AMENITY"."Amenity_ID" = 'AMTY1001') ORDER BY "BUILDING"."Building_Name" ASC, "VENUE"."Venue_Name" ASC;

-- 5. Available venues: no overlapping reservation or renovation
-- Used by: GET /venues/?start=2027-01-10T10:00&end=2027-01-10T11:00
SELECT "VENUE"."Venue_ID", "VENUE"."Venue_Name", "VENUE"."Venue_Type", "VENUE"."Floor", "VENUE"."Floor_Area_Sqm", "VENUE"."Capacity", "VENUE"."Building_ID", "BUILDING"."Building_ID", "BUILDING"."Building_Name", "BUILDING"."Street", "BUILDING"."District", "BUILDING"."City", "BUILDING"."Acquisition_Date" FROM "VENUE" INNER JOIN "BUILDING" ON ("VENUE"."Building_ID" = "BUILDING"."Building_ID") WHERE (NOT (EXISTS(SELECT 1 AS "a" FROM "RESERVATION" "U0" WHERE ("U0"."End_DateTime" > '2027-01-10 10:00:00' AND "U0"."Start_DateTime" < '2027-01-10 11:00:00' AND "U0"."Venue_ID" = ("VENUE"."Venue_ID")) LIMIT 1)) AND NOT (EXISTS(SELECT 1 AS "a" FROM "RENOVATION" "U0" WHERE ("U0"."Date_Started" <= '2027-01-10' AND "U0"."Venue_ID" = ("VENUE"."Venue_ID") AND ("U0"."Date_Completed" IS NULL OR "U0"."Date_Completed" >= '2027-01-10')) LIMIT 1))) ORDER BY "BUILDING"."Building_Name" ASC, "VENUE"."Venue_Name" ASC;

-- 6. Venue details with its building
-- Used by: GET /venues/00001001/
SELECT "VENUE"."Venue_ID", "VENUE"."Venue_Name", "VENUE"."Venue_Type", "VENUE"."Floor", "VENUE"."Floor_Area_Sqm", "VENUE"."Capacity", "VENUE"."Building_ID", "BUILDING"."Building_ID", "BUILDING"."Building_Name", "BUILDING"."Street", "BUILDING"."District", "BUILDING"."City", "BUILDING"."Acquisition_Date" FROM "VENUE" INNER JOIN "BUILDING" ON ("VENUE"."Building_ID" = "BUILDING"."Building_ID") WHERE "VENUE"."Venue_ID" = '00001001';

-- 7. Amenities installed in the venue
-- Used by: GET /venues/00001001/
SELECT "VENUE_AMENITY"."Venue_Amenity_ID", "VENUE_AMENITY"."Description", "VENUE_AMENITY"."Quantity", "VENUE_AMENITY"."Installation_Date", "VENUE_AMENITY"."Venue_ID", "VENUE_AMENITY"."Amenity_ID", "AMENITY_TYPE"."Amenity_ID", "AMENITY_TYPE"."Amenity_Name" FROM "VENUE_AMENITY" INNER JOIN "AMENITY_TYPE" ON ("VENUE_AMENITY"."Amenity_ID" = "AMENITY_TYPE"."Amenity_ID") WHERE "VENUE_AMENITY"."Venue_ID" = '00001001' ORDER BY "AMENITY_TYPE"."Amenity_Name" ASC;

-- 8. Agent currently assigned to the venue
-- Used by: GET /venues/00001001/
SELECT "VENUE_ASSIGNMENT"."Assignment_ID", "VENUE_ASSIGNMENT"."Start_Date", "VENUE_ASSIGNMENT"."End_Date", "VENUE_ASSIGNMENT"."Agent_ID", "VENUE_ASSIGNMENT"."Venue_ID", "AGENT"."Agent_ID", "AGENT"."First_Name", "AGENT"."Last_Name", "AGENT"."Building_ID" FROM "VENUE_ASSIGNMENT" INNER JOIN "AGENT" ON ("VENUE_ASSIGNMENT"."Agent_ID" = "AGENT"."Agent_ID") WHERE ("VENUE_ASSIGNMENT"."Start_Date" <= '2027-01-10' AND "VENUE_ASSIGNMENT"."Venue_ID" = '00001001' AND ("VENUE_ASSIGNMENT"."End_Date" IS NULL OR "VENUE_ASSIGNMENT"."End_Date" >= '2027-01-10')) ORDER BY "VENUE_ASSIGNMENT"."Start_Date" DESC LIMIT 1;

-- 9. Ongoing renovations of the venue
-- Used by: GET /venues/00001001/
SELECT "RENOVATION"."Renovation_ID", "RENOVATION"."Date_Started", "RENOVATION"."Date_Completed", "RENOVATION"."Remarks", "RENOVATION"."Venue_ID" FROM "RENOVATION" WHERE ("RENOVATION"."Date_Started" <= '2027-01-10' AND "RENOVATION"."Venue_ID" = '00001001' AND ("RENOVATION"."Date_Completed" IS NULL OR "RENOVATION"."Date_Completed" >= '2027-01-10'));

-- 10. Logged-in customer's reservations
-- Used by: GET /reservations/
SELECT "RESERVATION"."Reservation_ID", "RESERVATION"."Start_DateTime", "RESERVATION"."End_DateTime", "RESERVATION"."Expected_Participants", "RESERVATION"."Venue_ID", "RESERVATION"."Customer_ID", "VENUE"."Venue_ID", "VENUE"."Venue_Name", "VENUE"."Venue_Type", "VENUE"."Floor", "VENUE"."Floor_Area_Sqm", "VENUE"."Capacity", "VENUE"."Building_ID", "BUILDING"."Building_ID", "BUILDING"."Building_Name", "BUILDING"."Street", "BUILDING"."District", "BUILDING"."City", "BUILDING"."Acquisition_Date" FROM "RESERVATION" INNER JOIN "CUSTOMER" ON ("RESERVATION"."Customer_ID" = "CUSTOMER"."Customer_ID") INNER JOIN "useraccounts_profile" ON ("CUSTOMER"."Customer_ID" = "useraccounts_profile"."customer_id") INNER JOIN "VENUE" ON ("RESERVATION"."Venue_ID" = "VENUE"."Venue_ID") INNER JOIN "BUILDING" ON ("VENUE"."Building_ID" = "BUILDING"."Building_ID") WHERE "useraccounts_profile"."user_id" = 1 ORDER BY "RESERVATION"."Start_DateTime" ASC;

-- 11. Reservation summary (own reservations only)
-- Used by: GET /reservations/RSVN1001/
SELECT "RESERVATION"."Reservation_ID", "RESERVATION"."Start_DateTime", "RESERVATION"."End_DateTime", "RESERVATION"."Expected_Participants", "RESERVATION"."Venue_ID", "RESERVATION"."Customer_ID", "VENUE"."Venue_ID", "VENUE"."Venue_Name", "VENUE"."Venue_Type", "VENUE"."Floor", "VENUE"."Floor_Area_Sqm", "VENUE"."Capacity", "VENUE"."Building_ID", "BUILDING"."Building_ID", "BUILDING"."Building_Name", "BUILDING"."Street", "BUILDING"."District", "BUILDING"."City", "BUILDING"."Acquisition_Date" FROM "RESERVATION" INNER JOIN "CUSTOMER" ON ("RESERVATION"."Customer_ID" = "CUSTOMER"."Customer_ID") INNER JOIN "useraccounts_profile" ON ("CUSTOMER"."Customer_ID" = "useraccounts_profile"."customer_id") INNER JOIN "VENUE" ON ("RESERVATION"."Venue_ID" = "VENUE"."Venue_ID") INNER JOIN "BUILDING" ON ("VENUE"."Building_ID" = "BUILDING"."Building_ID") WHERE ("useraccounts_profile"."user_id" = 1 AND "RESERVATION"."Reservation_ID" = 'RSVN1001') ORDER BY "RESERVATION"."Start_DateTime" ASC;
